function design(site, analyse) {
  var X = [0,3.61,7.22,10.83,14.44,18.05,21.66,25.27,28.88,32.49,36.1];
  var N = [];
  for (var i = 0; i < 11; i++) {
    N.push({id:'BL'+i, x:X[i], y:-5.8, z:-4.15});
    N.push({id:'BR'+i, x:X[i], y:-5.8, z:4.15});
  }
  function B(cs, vs, ds, xs) {
    var m = [], P = [['L','BL'],['R','BR']];
    for (var p = 0; p < 2; p++) {
      var t = P[p][0], b = P[p][1];
      for (var i = 0; i < 10; i++) {
        m.push({a:t+i, b:t+(i+1), spec:cs[i]});
        m.push({a:b+i, b:b+(i+1), spec:cs[i]});
      }
      for (var i = 0; i < 11; i++) m.push({a:t+i, b:b+i, spec:vs});
      for (var i = 0; i < 10; i++) {
        if (i % 2 === 0) m.push({a:t+i, b:b+(i+1), spec:ds});
        else m.push({a:b+i, b:t+(i+1), spec:ds});
      }
    }
    for (var i = 0; i < 11; i++) {
      m.push({a:'BL'+i, b:'BR'+i, spec:xs});
      m.push({a:'L'+i, b:'R'+i, spec:xs});
    }
    for (var i = 0; i < 10; i++) {
      m.push({a:'BL'+i, b:'BR'+(i+1), spec:xs});
      m.push({a:'BR'+i, b:'BL'+(i+1), spec:xs});
      m.push({a:'L'+i, b:'R'+(i+1), spec:xs});
      m.push({a:'R'+i, b:'L'+(i+1), spec:xs});
    }
    return {note:'Warren truss', nodes:N, joints:{}, members:m};
  }
  var c1 = ['S460 CHS193.7x6.3','S460 CHS219.1x8','S460 CHS244.5x8','S460 CHS273x10','S460 CHS323.9x10','S460 CHS323.9x10','S460 CHS273x10','S460 CHS244.5x8','S460 CHS219.1x8','S460 CHS193.7x6.3'];
  var c2 = ['S460 CHS244.5x8','S460 CHS273x10','S460 CHS323.9x10','S460 CHS323.9x10','S460 CHS355.6x12.5','S460 CHS355.6x12.5','S460 CHS323.9x10','S460 CHS323.9x10','S460 CHS273x10','S460 CHS244.5x8'];
  var C = [
    [c1,'S355 CHS168.3x5','S355 CHS114.3x4','S355 CHS76.1x3.2'],
    [c1,'S355 CHS219.1x8','S355 CHS139.7x5','S355 CHS88.9x4'],
    [c2,'S355 CHS219.1x8','S355 CHS168.3x5','S355 CHS114.3x4'],
    [c2,'S355 CHS244.5x8','S355 CHS193.7x6.3','S355 CHS139.7x5']
  ];
  var best = null, bm = 1e18;
  for (var j = 0; j < C.length; j++) {
    var d = B(C[j][0], C[j][1], C[j][2], C[j][3]);
    try {
      var r = analyse(d);
      if (r && r.ok && r.mass < bm) { best = d; bm = r.mass; }
      if (r && r.ok) break;
    } catch(e) {}
  }
  return best || B(c2, 'S355 CHS244.5x8', 'S355 CHS193.7x6.3', 'S355 CHS139.7x5');
}

function design(site, analyse) {
  const xs = [0, 3.61, 7.22, 10.83, 14.44, 18.05, 21.66, 25.27, 28.88, 32.49, 36.1];
  const nodes = [];
  const links = [];
  const add = (a, b, group) => links.push({ a, b, group });

  for (let i = 0; i <= 10; i++) {
    nodes.push({ id: `BL${i}`, x: xs[i], y: -5.4, z: -4.15, joint: "pin" });
    nodes.push({ id: `BR${i}`, x: xs[i], y: -5.4, z: 4.15, joint: "pin" });
  }

  // Twin side trusses: chords, posts, and Pratt diagonals sloping toward midspan.
  for (let i = 0; i < 10; i++) {
    add(`L${i}`, `L${i + 1}`, "chord");
    add(`R${i}`, `R${i + 1}`, "chord");
    add(`BL${i}`, `BL${i + 1}`, "chord");
    add(`BR${i}`, `BR${i + 1}`, "chord");

    if (i < 5) {
      add(`L${i}`, `BL${i + 1}`, "web");
      add(`R${i}`, `BR${i + 1}`, "web");
    } else {
      add(`BL${i}`, `L${i + 1}`, "web");
      add(`BR${i}`, `R${i + 1}`, "web");
    }
  }

  for (let i = 0; i <= 10; i++) {
    add(`L${i}`, `BL${i}`, "post");
    add(`R${i}`, `BR${i}`, "post");

    // Transverse ties and a diagonal in each vertical cross-frame.
    add(`L${i}`, `R${i}`, "tie");
    add(`BL${i}`, `BR${i}`, "tie");
    add(`L${i}`, `BR${i}`, "frame");
  }

  // X-bracing in the deck plane and in the lower plane.
  for (let i = 0; i < 10; i++) {
    add(`L${i}`, `R${i + 1}`, "plan");
    add(`R${i}`, `L${i + 1}`, "plan");
    add(`BL${i}`, `BR${i + 1}`, "plan");
    add(`BR${i}`, `BL${i + 1}`, "plan");
  }

  const options = {
    chord: [
      "S460 CHS193.7x8", "S460 CHS219.1x8", "S460 CHS244.5x8",
      "S460 CHS273x10", "S460 CHS323.9x10", "S460 CHS355.6x12.5",
      "S460 CHS406.4x12.5", "S460 CHS457x16"
    ],
    web: [
      "S460 CHS168.3x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS244.5x8", "S460 CHS273x10", "S460 CHS323.9x10",
      "S460 CHS355.6x12.5", "S460 CHS406.4x12.5", "S460 CHS457x16"
    ],
    post: [
      "S460 CHS114.3x5", "S460 CHS139.7x5", "S460 CHS139.7x6.3",
      "S460 CHS168.3x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS244.5x8", "S460 CHS273x10"
    ],
    tie: [
      "S460 CHS114.3x5", "S460 CHS139.7x6.3", "S460 CHS168.3x6.3",
      "S460 CHS193.7x8", "S460 CHS219.1x8", "S460 CHS244.5x8",
      "S460 CHS273x10", "S460 CHS323.9x10"
    ],
    frame: [
      "S460 CHS168.3x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS244.5x8", "S460 CHS273x10", "S460 CHS323.9x10",
      "S460 CHS355.6x12.5", "S460 CHS406.4x12.5", "S460 CHS457x16"
    ],
    plan: [
      "S460 CHS76.1x4", "S460 CHS88.9x4", "S460 CHS114.3x4",
      "S460 CHS114.3x5", "S460 CHS139.7x5", "S460 CHS139.7x6.3",
      "S460 CHS168.3x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS244.5x8"
    ]
  };

  const index = {
    chord: 5,  // CHS355.6x12.5
    web: 6,    // CHS355.6x12.5
    post: 5,   // CHS219.1x8
    tie: 5,    // CHS244.5x8
    frame: 5,  // CHS323.9x10
    plan: 7    // CHS193.7x8
  };

  const note =
    "Twin under-deck Pratt trusses with triangulated transverse frames and X-braced top and bottom planes; all joints are pinned.";

  function make(ix) {
    return {
      note,
      nodes,
      joints: {},
      members: links.map(m => ({
        a: m.a,
        b: m.b,
        spec: options[m.group][ix[m.group]]
      }))
    };
  }

  function acceptable(r) {
    if (!r || r.error || r.ok !== true) return false;

    const finite = v => typeof v === "number" && Number.isFinite(v);

    if (finite(r.maxUtil) && r.maxUtil > 0.70) return false;
    if (finite(r.alphaCrMin) && r.alphaCrMin < 4.0) return false;

    if (finite(r.frequency)) {
      const fmin = finite(r.fMin) ? r.fMin : 2.8;
      if (r.frequency < Math.max(3.15, 1.1 * fmin)) return false;
    }

    if (finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0 &&
        r.sag > 0.82 * r.sagLimit) return false;
    if (finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0 &&
        r.sway > 0.82 * r.swayLimit) return false;

    // Treat small fatigueWorst values as a utilization ratio, if that is
    // how the analysis engine reports it.
    if (finite(r.fatigueWorst) && r.fatigueWorst >= 0 &&
        r.fatigueWorst <= 1.5 && r.fatigueWorst > 0.75) return false;

    return true;
  }

  let result = analyse(make(index));

  // If needed, first grow all section groups until a conservative candidate passes.
  for (let k = 0; k < 10 && !acceptable(result); k++) {
    const next = Object.assign({}, index);
    let grew = false;
    for (const g of Object.keys(options)) {
      if (next[g] < options[g].length - 1) {
        next[g]++;
        grew = true;
      }
    }
    if (!grew) break;
    Object.assign(index, next);
    result = analyse(make(index));
  }

  // Greedily reduce each group while retaining the analysis margin.
  for (let pass = 0; pass < 4; pass++) {
    let changed = false;
    for (const g of ["plan", "post", "tie", "frame", "web", "chord"]) {
      while (index[g] > 0) {
        const trial = Object.assign({}, index);
        trial[g]--;
        const r = analyse(make(trial));
        if (!acceptable(r)) break;
        Object.assign(index, trial);
        result = r;
        changed = true;
      }
    }
    if (!changed) break;
  }

  return make(index);
}

function design(site, analyse) {
  const xs = [0, 3.61, 7.22, 10.83, 14.44, 18.05, 21.66, 25.27, 28.88, 32.49, 36.1];
  const nodes = [];
  const links = [];

  const menus = {
    top: [
      "S460 CHS168.3x6.3", "S460 CHS193.7x6.3", "S460 CHS193.7x8",
      "S460 CHS219.1x8", "S460 CHS244.5x8", "S460 CHS273x10",
      "S460 CHS323.9x10", "S460 CHS355.6x12.5"
    ],
    bottom: [
      "S460 CHS114.3x5", "S460 CHS139.7x5", "S460 CHS139.7x6.3",
      "S460 CHS168.3x6.3", "S460 CHS193.7x6.3", "S460 CHS193.7x8",
      "S460 CHS219.1x8", "S460 CHS244.5x8", "S460 CHS273x10",
      "S460 CHS323.9x10"
    ],
    web: [
      "S460 CHS88.9x4", "S460 CHS114.3x4", "S460 CHS114.3x5",
      "S460 CHS139.7x5", "S460 CHS139.7x6.3", "S460 CHS168.3x6.3",
      "S460 CHS193.7x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS244.5x8", "S460 CHS273x10", "S460 CHS323.9x10"
    ],
    post: [
      "S460 CHS88.9x4", "S460 CHS88.9x5", "S460 CHS114.3x4",
      "S460 CHS114.3x5", "S460 CHS139.7x5", "S460 CHS139.7x6.3",
      "S460 CHS168.3x6.3", "S460 CHS193.7x6.3", "S460 CHS193.7x8",
      "S460 CHS219.1x8", "S460 CHS244.5x8", "S460 CHS273x10",
      "S460 CHS323.9x10"
    ],
    tie: [
      "S460 CHS60.3x3.2", "S460 CHS76.1x3.2", "S460 CHS76.1x4",
      "S460 CHS88.9x4", "S460 CHS88.9x5", "S460 CHS114.3x4",
      "S460 CHS114.3x5", "S460 CHS139.7x5", "S460 CHS139.7x6.3",
      "S460 CHS168.3x6.3", "S460 CHS193.7x8"
    ],
    frame: [
      "S460 CHS76.1x4", "S460 CHS88.9x4", "S460 CHS88.9x5",
      "S460 CHS114.3x4", "S460 CHS114.3x5", "S460 CHS139.7x5",
      "S460 CHS139.7x6.3", "S460 CHS168.3x6.3",
      "S460 CHS193.7x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS244.5x8", "S460 CHS273x10", "S460 CHS323.9x10"
    ],
    planTop: [
      "S460 CHS139.7x5", "S460 CHS139.7x6.3", "S460 CHS168.3x6.3",
      "S460 CHS193.7x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS244.5x8", "S460 CHS273x10", "S460 CHS323.9x10",
      "S460 CHS355.6x12.5"
    ],
    planBottom: [
      "S460 CHS88.9x4", "S460 CHS88.9x5", "S460 CHS114.3x4",
      "S460 CHS114.3x5", "S460 CHS139.7x5", "S460 CHS139.7x6.3",
      "S460 CHS168.3x6.3", "S460 CHS193.7x6.3", "S460 CHS193.7x8",
      "S460 CHS219.1x8", "S460 CHS244.5x8", "S460 CHS273x10",
      "S460 CHS323.9x10"
    ]
  };

  const initial = {
    top: 5, bottom: 7, web: 9, post: 10, tie: 9,
    frame: 10, planTop: 6, planBottom: 7
  };

  for (let i = 0; i <= 10; i++) {
    nodes.push({ id: `BL${i}`, x: xs[i], y: -5.84, z: -4.15, joint: "pin" });
    nodes.push({ id: `BR${i}`, x: xs[i], y: -5.84, z: 4.15, joint: "pin" });
  }

  const add = (a, b, g) => links.push({ a, b, g, i: initial[g] });

  for (let i = 0; i < 10; i++) {
    add(`L${i}`, `L${i + 1}`, "top");
    add(`R${i}`, `R${i + 1}`, "top");
    add(`BL${i}`, `BL${i + 1}`, "bottom");
    add(`BR${i}`, `BR${i + 1}`, "bottom");

    if (i < 5) {
      add(`L${i}`, `BL${i + 1}`, "web");
      add(`R${i}`, `BR${i + 1}`, "web");
    } else {
      add(`BL${i}`, `L${i + 1}`, "web");
      add(`BR${i}`, `R${i + 1}`, "web");
    }

    // X bracing in the deck plane and lower plane.
    add(`L${i}`, `R${i + 1}`, "planTop");
    add(`R${i}`, `L${i + 1}`, "planTop");
    add(`BL${i}`, `BR${i + 1}`, "planBottom");
    add(`BR${i}`, `BL${i + 1}`, "planBottom");
  }

  for (let i = 0; i <= 10; i++) {
    add(`L${i}`, `BL${i}`, "post");
    add(`R${i}`, `BR${i}`, "post");
    add(`L${i}`, `R${i}`, "tie");
    add(`BL${i}`, `BR${i}`, "tie");

    // A diagonal braces each transverse frame; alternate its orientation.
    if (i % 2 === 0) add(`L${i}`, `BR${i}`, "frame");
    else add(`R${i}`, `BL${i}`, "frame");
  }

  const note =
    "Full-depth pinned Pratt trusses with independently sized top and bottom bracing, replacing the previous uniformly oversized sections.";

  function make() {
    return {
      note,
      nodes: nodes.map(n => ({ ...n })),
      joints: {},
      members: links.map(m => ({
        a: m.a,
        b: m.b,
        spec: menus[m.g][m.i]
      }))
    };
  }

  const finite = v => typeof v === "number" && Number.isFinite(v);
  let calls = 0;
  const limit = 300;

  function run() {
    if (calls >= limit) return null;
    calls++;
    return analyse(make());
  }

  function acceptable(r) {
    if (!r || r.error || r.ok !== true) return false;
    if (finite(r.maxUtil) && r.maxUtil > 0.82) return false;
    if (finite(r.alphaCrMin) && r.alphaCrMin < 5.0) return false;
    if (finite(r.frequency) && r.frequency < 3.05) return false;
    if (finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0 &&
        r.sag > 0.88 * r.sagLimit) return false;
    if (finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0 &&
        r.sway > 0.88 * r.swayLimit) return false;
    if (finite(r.fatigueWorst) && r.fatigueWorst >= 0 &&
        r.fatigueWorst <= 2 && r.fatigueWorst > 0.82) return false;

    if (Array.isArray(r.members)) {
      for (const q of r.members) {
        const mode = String(q.mode || "").toLowerCase();
        if (mode && !mode.includes("fatigue") &&
            finite(q.util) && q.util > 0.76) return false;
      }
    }
    return true;
  }

  const pairKey = (a, b) => a < b ? `${a}|${b}` : `${b}|${a}`;

  function reportMap(r) {
    const map = {};
    if (!r || !Array.isArray(r.members)) return map;
    for (const q of r.members) {
      let a = q.a;
      let b = q.b;
      if (!a || !b) {
        const parts = String(q.id || "").split("-");
        if (parts.length === 2) {
          a = parts[0];
          b = parts[1];
        }
      }
      if (a && b) map[pairKey(a, b)] = q;
    }
    return map;
  }

  function grow(r) {
    const bump = groups => {
      let changed = false;
      for (const m of links) {
        if (groups.includes(m.g) && m.i + 1 < menus[m.g].length) {
          m.i++;
          changed = true;
        }
      }
      return changed;
    };

    if (r && finite(r.alphaCrMin) && r.alphaCrMin < 5.0) {
      return bump(Object.keys(menus));
    }
    if (r && finite(r.frequency) && r.frequency < 3.05) {
      return bump(["top", "bottom", "web", "post", "tie", "frame", "planTop", "planBottom"]);
    }
    if (r && finite(r.sag) && finite(r.sagLimit) && r.sagLimit > 0 &&
        r.sag > 0.88 * r.sagLimit) {
      return bump(["top", "bottom", "web", "post"]);
    }
    if (r && finite(r.sway) && finite(r.swayLimit) && r.swayLimit > 0 &&
        r.sway > 0.88 * r.swayLimit) {
      return bump(["tie", "frame", "planTop", "planBottom"]);
    }

    const map = reportMap(r);
    const ranked = [];
    for (const m of links) {
      const q = map[pairKey(m.a, m.b)];
      if (q && finite(q.util) && m.i + 1 < menus[m.g].length) {
        ranked.push({ m, u: q.util });
      }
    }
    ranked.sort((a, b) => b.u - a.u);

    let changed = false;
    for (const item of ranked.slice(0, 8)) {
      item.m.i++;
      changed = true;
    }
    if (changed) return true;

    const fatigueHigh = r && finite(r.fatigueWorst) && r.fatigueWorst > 0.82;
    return bump(fatigueHigh
      ? ["planTop", "planBottom", "top", "bottom", "web"]
      : Object.keys(menus));
  }

  let result = run();

  for (let k = 0; k < 28 && !acceptable(result) && calls < limit; k++) {
    if (!grow(result)) break;
    const next = run();
    if (!next) break;
    result = next;
  }

  if (!acceptable(result) && calls < limit) {
    for (const m of links) m.i = menus[m.g].length - 1;
    const fallback = run();
    if (fallback) result = fallback;
  }

  if (acceptable(result)) {
    const groupOrder = [
      "planBottom", "frame", "tie", "post",
      "web", "bottom", "top", "planTop"
    ];

    for (const g of groupOrder) {
      while (calls < limit) {
        const changed = [];
        for (const m of links) {
          if (m.g === g && m.i > 0) {
            m.i--;
            changed.push(m);
          }
        }
        if (changed.length === 0) break;

        const trial = run();
        if (acceptable(trial)) {
          result = trial;
        } else {
          for (const m of changed) m.i++;
          break;
        }
      }
    }

    const priority = {
      planBottom: 0, frame: 1, tie: 2, post: 3,
      web: 4, bottom: 5, top: 6, planTop: 7
    };
    const order = links.slice().sort((a, b) => priority[a.g] - priority[b.g]);

    for (let pass = 0; pass < 2 && calls < limit; pass++) {
      let reduced = false;
      for (const m of order) {
        if (calls >= limit) break;
        if (m.i === 0) continue;

        const old = m.i;
        m.i--;
        const trial = run();
        if (acceptable(trial)) {
          result = trial;
          reduced = true;
        } else {
          m.i = old;
        }
      }
      if (!reduced) break;
    }
  }

  return make();
}

function design(site, analyse) {
  const pitch = 3.61;
  const nodes = [];

  // Bottom nodes sit halfway between deck stations, giving each deck node
  // two short Warren webs on each side truss.
  for (let j = 0; j < 10; j++) {
    const x = (j + 0.5) * pitch;
    nodes.push({ id: `BL${j}`, x, y: -5.84, z: -4.15, joint: "pin" });
    nodes.push({ id: `BR${j}`, x, y: -5.84, z: 4.15, joint: "pin" });
  }

  const menus = {
    top: [
      "S460 CHS168.3x6.3", "S460 CHS193.7x6.3", "S460 CHS193.7x8",
      "S460 CHS219.1x8", "S460 CHS244.5x8", "S460 CHS273x10",
      "S460 CHS323.9x10", "S460 CHS355.6x12.5", "S460 CHS406.4x12.5"
    ],
    bottom: [
      "S460 CHS114.3x5", "S460 CHS139.7x5", "S460 CHS139.7x6.3",
      "S460 CHS168.3x6.3", "S460 CHS193.7x6.3", "S460 CHS193.7x8",
      "S460 CHS219.1x8", "S460 CHS244.5x8", "S460 CHS273x10",
      "S460 CHS323.9x10", "S460 CHS355.6x12.5"
    ],
    web: [
      "S460 CHS76.1x4", "S460 CHS88.9x4", "S460 CHS114.3x4",
      "S460 CHS114.3x5", "S460 CHS139.7x5", "S460 CHS139.7x6.3",
      "S460 CHS168.3x6.3", "S460 CHS193.7x6.3", "S460 CHS193.7x8",
      "S460 CHS219.1x8", "S460 CHS244.5x8", "S460 CHS273x10"
    ],
