      for (let k = 0; k < 4 && m.i > 0 && calls < MAX_CALLS; k++) {
        const old = m.i;
        m.i = old - 1;
        const trial = run();
        if (safe(trial)) {
          currentResult = trial;
          remember(trial);
        } else {
          m.i = old;
          break;
        }
      }
    }
  }

  // Use any remaining analyses for one more low-utilisation reduction pass.
  if (safe(currentResult) && calls < MAX_CALLS) {
    const map = reportMap(currentResult);
    const ranked = links.map(m => {
      const q = map[pairKey(m.a, m.b)];
      return {
        m,
        u: q && finite(q.util) ? q.util : 0.45,
        saving: m.i > 0
          ? massAt(m, m.i, m.mat) - massAt(m, m.i - 1, m.mat)
