      if (calls >= MAX_CALLS) break;
      const m = item.m;
      if (m.i <= 0) continue;

      const old = m.i;
      m.i = old - 1;
      const trial = run();
      if (safe(trial)) {
        currentResult = trial;
        remember(trial);
      } else {
        m.i = old;
      }
    }
  }

  if (bestSafeState) restore(bestSafeState);
  else if (bestPassState) restore(bestPassState);
  else restore(startState);

  return make();
}

