        const old = unit.links[0].i;
        for (const m of unit.links) m.i = old - 1;
        trial = run();

        if (safe(trial)) {
          currentResult = trial;
          remember(trial);
        } else {
          for (const m of unit.links) m.i = old;
          break;
        }
      }
    }
  }

