      links[i].i = state[i].i;
      links[i].mat = state[i].mat;
    }
  };

  let currentResult = run();
  if (currentResult && finite(currentResult.maxUtil)) {
    referenceMaxUtil = currentResult.maxUtil;
  }

  const startState = snapshot();
  let bestSafeState = null;
  let bestSafeMass = Infinity;
  let bestPassState = null;
  let bestPassMass = Infinity;

  function remember(r) {
    if (!r || r.error || !finite(r.mass)) return;

    if (r.ok === true && r.mass < bestPassMass) {
      bestPassMass = r.mass;
      bestPassState = snapshot();
    }
    if (acceptable(r) && r.mass < bestSafeMass) {
      bestSafeMass = r.mass;
      bestSafeState = snapshot();
    }
  }

  remember(currentResult);

  const steelDensity = 7850;
  const aluminiumDensity = 2810;
  const massAt = (m, i, mat) =>
    areas[i] * 1e-4 *
    (mat === "AL7075" ? aluminiumDensity : steelDensity) * m.len;

  function tryReduction(m, usage, limit, blocked) {
    if (calls >= limit || m.i <= 0) return false;

    const oldI = m.i;
    const signature = `${m.a}|${m.b}|${m.mat}|${oldI}`;
    if (blocked.has(signature)) return false;

    const jump = usage < 0.12 ? 5 :
                 usage < 0.22 ? 3 :
                 usage < 0.35 ? 2 : 1;

    m.i = Math.max(0, oldI - jump);
    let trial = run();

    if (acceptable(trial)) {
      currentResult = trial;
      remember(trial);
      return true;
    }

    m.i = oldI;

    if (jump > 1 && calls < limit) {
      m.i = oldI - 1;
      trial = run();
      if (acceptable(trial)) {
        currentResult = trial;
        remember(trial);
        return true;
      }
      m.i = oldI;
    }

    blocked.add(signature);
    return false;
  }

  function optimizeSections(limit, blocked) {
    if (!acceptable(currentResult)) return;

    for (let pass = 0; pass < 6 && calls < limit; pass++) {
      const map = memberMap(currentResult);
      const order = links.map(m => {
        const q = map.get(pairKey(m.a, m.b));
        const usage = q && finite(q.util) ? Math.max(0, q.util) : 0.50;
        const saving = m.i > 0
          ? massAt(m, m.i, m.mat) - massAt(m, m.i - 1, m.mat)
          : 0;
        return { m, usage, saving };
      }).sort((a, b) =>
        a.usage !== b.usage
          ? a.usage - b.usage
          : b.saving - a.saving
      );

      let changed = false;
      for (const item of order) {
        if (calls >= limit) break;
        if (tryReduction(item.m, item.usage, limit, blocked)) changed = true;
      }
      if (!changed) break;
    }
  }

  optimizeSections(270, new Set());

  // Test lighter aluminium only on low-utilisation, non-fatigue-governed members.
  if (acceptable(currentResult)) {
    const map = memberMap(currentResult);
    const candidates = [];

    for (const m of links) {
      if (m.mat !== "S460") continue;
      const q = map.get(pairKey(m.a, m.b));
      if (!q || !finite(q.util) || q.util > 0.34) continue;
      if (String(q.mode || "").toLowerCase().includes("fatigue")) continue;

      const steelMass = massAt(m, m.i, "S460");
      candidates.push({
        m,
        priority: steelMass * (1 - aluminiumDensity / steelDensity) /
                  (0.20 + Math.max(0, q.util))
      });
    }

    candidates.sort((a, b) => b.priority - a.priority);

    for (const item of candidates) {
      if (calls >= 350) break;
      const m = item.m;
      if (m.mat !== "S460") continue;

      const oldMat = m.mat;
      m.mat = "AL7075";
      let trial = run();

      if (!acceptable(trial)) {
        m.mat = oldMat;
        continue;
      }

      currentResult = trial;
      remember(trial);

      while (m.i > 0 && calls < 350) {
        const oldI = m.i;
        m.i = oldI - 1;
        trial = run();

        if (acceptable(trial)) {
          currentResult = trial;
          remember(trial);
        } else {
          m.i = oldI;
          break;
        }
      }
    }
  }

  // Use S690 one size smaller where strength, rather than buckling or fatigue, governs.
  if (acceptable(currentResult)) {
    const map = memberMap(currentResult);
    const candidates = [];

    for (const m of links) {
      if (m.mat !== "S460" || m.i <= 0) continue;
      const q = map.get(pairKey(m.a, m.b));
      if (!q || !finite(q.util) || q.util > 0.70) continue;

      const mode = String(q.mode || "").toLowerCase();
      if (mode.includes("fatigue") || mode.includes("buckl")) continue;

      const saving = massAt(m, m.i, "S460") -
                     massAt(m, m.i - 1, "S460");
      candidates.push({
        m,
        priority: saving / (0.20 + Math.max(0, q.util))
      });
    }

    candidates.sort((a, b) => b.priority - a.priority);

    for (const item of candidates) {
      if (calls >= 385) break;
      const m = item.m;
      if (m.mat !== "S460" || m.i <= 0) continue;

      const oldMat = m.mat;
      const oldI = m.i;
      m.mat = "S690";
      m.i = oldI - 1;
      let trial = run();

      if (!acceptable(trial)) {
        m.mat = oldMat;
        m.i = oldI;
        continue;
      }

      currentResult = trial;
      remember(trial);

      while (m.i > 0 && calls < 385) {
        const old = m.i;
        m.i = old - 1;
        trial = run();

        if (acceptable(trial)) {
          currentResult = trial;
          remember(trial);
        } else {
          m.i = old;
          break;
        }
      }
    }
  }

  optimizeSections(390, new Set());

  if (bestSafeState) restore(bestSafeState);
  else if (bestPassState) restore(bestPassState);
  else restore(startState);

  return make();
}

