  function optimize(init, useTopDiagonals, rigidDeck) {
    let current = init.slice();
    let result = safeAnalyse(makeDesign(current, useTopDiagonals, rigidDeck));
    if (!result || result.error) return null;
    while (!result.ok && totalEval < maxTotalEval) {
      let worstIndex = -1;
      let worstUtil = -1;
      if (result.members) {
        for (let i = 0; i < result.members.length; i++) {
          if (result.members[i].util > worstUtil) {
