          let trial = current.slice();
          trial[g]--;
          let trialResult = safeAnalyse(makeDesign(trial, useTopDiagonals, rigidDeck));
          if (!trialResult || trialResult.error) continue;
          if (trialResult.ok && trialResult.mass < result.mass) {
            current = trial;
            result = trialResult;
