  let best = null;
  if (bestA && bestB) {
    best = bestA.mass < bestB.mass ? bestA : bestB;
  } else {
    best = bestA || bestB;
  }

  if (!best) {
    const fallbackSections = new Array(17).fill(23);
    return makeDesign(fallbackSections, true, false);
  }

  return best.design;
}

