      nodes.push({ id: "BR" + i, x: i * 3.61, y: -h, z:  4.15, joint: "pin" });
    }

    const members = [];
    function add(a, b, g) {
      members.push([a, b, "S690 " + SECTIONS[idx[g]]]);
    }

    // Top chord panels: symmetric pairs (0,9), (1,8), ..., (4,5).
    for (let p = 0; p <= 4; p++) {
      const q = 9 - p;
      for (const s of ["L", "R"]) {
        add(s + p, s + (p + 1), p);
        add(s + q, s + (q + 1), p);
      }
    }

