    function addBottomSegment(k, g) {
      for (const s of ["L", "R"]) {
        const pre = (s === "L" ? "BL" : "BR");
        let a, b;
        if (k === 0) { a = s + "0"; b = pre + "1"; }
        else if (k === 9) { a = pre + "9"; b = s + "10"; }
        else { a = pre + k; b = pre + (k + 1); }
        add(a, b, g);
      }
    }
    for (let p = 0; p <= 4; p++) {
      const q = 9 - p;
      const g = 5 + p;
      addBottomSegment(p, g);
      addBottomSegment(q, g);
    }

