    };
  }

  let calls = 0;
  const MAX_CALLS = 390;
  const cache = {};

  function evalIndices(indices) {
    const key = indices.join(",");
    if (cache[key] !== undefined) return cache[key];
    if (calls >= MAX_CALLS) return null;
    let r;
    try {
      r = analyse(makeDesign(indices));
    } catch (e) {
      r = { error: String(e) };
    }
    calls++;
    cache[key] = r;
    return r;
  }

  function within(r, th) {
    if (!r || r.error || !r.ok) return false;

    if (typeof r.alphaCr === "number" && r.alphaCr < th.alpha) return false;
    if (typeof r.frequency === "number" && r.frequency < th.freq) return false;

    if (typeof r.sag === "number") {
      const lim = (typeof r.sagLimit === "number" ? r.sagLimit : 120.3);
      if (r.sag > lim * th.sagFactor) return false;
    }
    if (typeof r.sway === "number") {
      const lim = (typeof r.swayLimit === "number" ? r.swayLimit : 90.3);
      if (r.sway > lim * th.swayFactor) return false;
    }

    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > th.fatigue) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > th.maxUtil) return false;

    if (r.members) {
      for (let i = 0; i < r.members.length; i++) {
        const m = r.members[i];
        if (m && typeof m.util === "number" && m.util > th.maxUtil) return false;
      }
    }
    if (r.cases) {
      for (let i = 0; i < r.cases.length; i++) {
        const c = r.cases[i];
        if (c && typeof c.maxUtil === "number" && c.maxUtil > th.maxUtil) return false;
      }
    }

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" && r.robustness.ok === false) return false;

    return true;
  }

  function optimize(start, th, maxPasses) {
    let cur = start.slice();
    let r0 = evalIndices(cur);
    if (!r0 || !within(r0, th)) return null;

    let best = { indices: cur.slice(), mass: r0.mass, result: r0 };

    for (let pass = 0; pass < maxPasses && calls < MAX_CALLS - 5; pass++) {
      let improved = false;

      for (let g = 0; g < NUM_GROUPS && calls < MAX_CALLS - 5; g++) {
        if (cur[g] <= MINIDX[g]) continue;

        let lo = MINIDX[g];
        let hi = cur[g];
