          }
        }

        if (ans < cur[g]) {
          cur[g] = ans;
          improved = true;
          const rr = evalIndices(cur);
          if (rr && within(rr, th) && rr.mass < best.mass) {
            best = { indices: cur.slice(), mass: rr.mass, result: rr };
          }
        }
      }

      if (!improved) break;
    }

    const rr = evalIndices(cur);
    if (rr && within(rr, th) && rr.mass < best.mass) {
      best = { indices: cur.slice(), mass: rr.mass, result: rr };
    }

