  const startEst = [
    19, 19, 19, 19, 19,
    19, 19, 19, 19, 19,
    16, 16, 16, 16, 16,
    18, 18, 18, 18,
    14, 14, 12, 12, 12
  ];

  // Main conservative thresholds, similar to the proven attempt-2 margins.
  const TH = {
    maxUtil: 0.75,
    fatigue: 0.66,
    alpha: 5.0,
    freq: 3.05,
    sagFactor: 0.65,
    swayFactor: 0.65
  };

  let fallback = null;
  const rEst = evalIndices(startEst);
  if (rEst && rEst.ok) fallback = { indices: startEst.slice(), mass: rEst.mass, result: rEst };

  let best = null;
  if (rEst && within(rEst, TH)) {
    best = optimize(startEst, TH, 3);
  }

  if (!best && calls < MAX_CALLS - 5) {
    const rMax = evalIndices(allMax);
    if (rMax && within(rMax, TH)) {
      best = optimize(allMax, TH, 2);
    } else {
      // Slightly relaxed but still conservative fallback, only if the strict
      // profile cannot be met because of discrete section jumps.
      const TH2 = {
        maxUtil: 0.82,
        fatigue: 0.74,
        alpha: 4.2,
        freq: 2.95,
        sagFactor: 0.82,
        swayFactor: 0.82
      };
      if (rEst && within(rEst, TH2)) {
        best = optimize(startEst, TH2, 2);
      } else if (rMax && within(rMax, TH2)) {
        best = optimize(allMax, TH2, 2);
      }
    }
  }

  if (best) return makeDesign(best.indices);
  if (fallback) return makeDesign(fallback.indices);
  return makeDesign(allMax);
}

