    for (let i = 0; i <= 9; i++) {
      const g = 10 + Math.min(i, 9 - i);
      add("C" + i, "L" + i, g);
      add("C" + i, "R" + i, g);
      add("C" + i, "L" + (i + 1), g);
      add("C" + i, "R" + (i + 1), g);
