    for (let i = 0; i <= 10; i++) {
      nodes.push({
        id: "N" + i,
        x: i * dx,
        y: 0,
        z: 0,
        joint: "pin"
      });
    }

    const members = [];
    function add(a, b, g) {
      if (!a || !b || a === b) throw new Error("bad member " + a + " " + b);
      members.push([a, b, sec(g)]);
    }

    // Top edge chords.
    for (let p = 0; p < 10; p++) {
      const g = Math.min(p, 9 - p);
      add("L" + p, "L" + (p + 1), g);
      add("R" + p, "R" + (p + 1), g);
    }

    // Central bottom chord.
    for (let i = 0; i <= 8; i++) {
      const g = 5 + Math.min(i, 8 - i);
      add("C" + i, "C" + (i + 1), g);
    }

    // Main inclined web from central bottom spine to top edge stations.
    for (let i = 0; i <= 9; i++) {
      const g = 10 + Math.min(i, 9 - i);
      add("C" + i, "L" + i, g);
      add("C" + i, "R" + i, g);
      add("C" + i, "L" + (i + 1), g);
      add("C" + i, "R" + (i + 1), g);
    }

    // Top transverse ties, split at a braced centre node N_i.
    for (let i = 0; i <= 10; i++) {
      const g = 15 + Math.min(i, 10 - i);
      add("L" + i, "N" + i, g);
      add("N" + i, "R" + i, g);
    }

    // Top-plane bracing, split at mid-panel nodes M_i.
    for (let p = 0; p < 10; p++) {
      const g = 21 + Math.min(p, 9 - p);
      if (p % 2 === 0) {
        add("L" + p, "M" + p, g);
        add("M" + p, "R" + (p + 1), g);
      } else {
        add("R" + p, "M" + p, g);
        add("M" + p, "L" + (p + 1), g);
      }
    }

    // Vertical posts from mid-panel top centre to bottom spine.
    for (let i = 0; i <= 9; i++) {
      const g = 26 + Math.min(i, 9 - i);
      add("M" + i, "C" + i, g);
    }

    // Vee braces from station centre node N_i to adjacent bottom spine nodes.
    for (let i = 0; i <= 10; i++) {
      const g = 31 + Math.min(i, 10 - i);
      if (i > 0) add("N" + i, "C" + (i - 1), g);
      if (i < 10) add("N" + i, "C" + i, g);
    }

    // Continuous central top chord N0-M0-N1-M1-...-N10.
    for (let i = 0; i <= 9; i++) {
      const g = 37 + Math.min(i, 9 - i);
      add("N" + i, "M" + i, g);
      add("M" + i, "N" + (i + 1), g);
    }

