      note: "S690 CHS central-spine bridge with added braced central top chord, split transverse ties and split top-plane bracing",
      nodes: nodes,
      joints: {},
      members: members
    };
  }

  const MAX_CALLS = 398;
  let calls = 0;
  const cache = {};

  function evaluate(type, idx, H) {
    H = H || H_SPLIT;
    const key = type + ":" + (type === "split" ? H : 0) + ":" + idx.join(",");
    if (cache[key] !== undefined) return cache[key];
    if (calls >= MAX_CALLS) return null;

    let d;
    try {
      d = (type === "base") ? makeBase(idx) : makeSplit(idx, H);
    } catch (e) {
      calls++;
      cache[key] = { error: String(e) };
      return cache[key];
    }

    let r;
    try {
      r = analyse(d);
    } catch (e) {
      r = { error: String(e) };
    }
