    return (r && typeof r.mass === "number") ? r.mass : Infinity;
  }

  function within(r, th) {
    if (!r || r.error || r.ok === false) return false;

    const ac = (typeof r.alphaCr === "number") ? r.alphaCr : r.alphaCrMin;
    if (typeof ac === "number" && ac < th.alpha) return false;

    if (typeof r.frequency === "number" && r.frequency < th.freq) return false;

    if (typeof r.sag === "number") {
      const lim = (typeof r.sagLimit === "number") ? r.sagLimit : 120.3;
      if (r.sag > lim * th.sagFactor) return false;
    }
    if (typeof r.sway === "number") {
      const lim = (typeof r.swayLimit === "number") ? r.swayLimit : 90.3;
      if (r.sway > lim * th.swayFactor) return false;
    }

    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > th.fatigue) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > th.maxUtil) return false;

    if (r.members) {
      for (let i = 0; i < r.members.length; i++) {
        const m = r.members[i];
        if (m && typeof m.util === "number" && m.util > th.maxUtil) return false;
      }
    }
    if (r.cases) {
      for (let i = 0; i < r.cases.length; i++) {
        const c = r.cases[i];
        if (c && typeof c.maxUtil === "number" && c.maxUtil > th.maxUtil) return false;
      }
    }

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" && r.robustness.ok === false) return false;

    return true;
  }

  const TH_SAFE = {
    maxUtil: 0.74,
    fatigue: 0.74,
    alpha: 4.8,
    freq: 2.95,
    sagFactor: 0.95,
    swayFactor: 0.95
  };

  function findValidStart(start, type, th) {
    const H = (type === "split") ? H_SPLIT : undefined;
    let r0 = evaluate(type, start, H);
    if (r0 && within(r0, th)) {
      return { idx: start.slice(), res: r0 };
    }

    // First strengthen only the new groups.
    for (let add = 1; add <= 8; add++) {
      if (calls >= MAX_CALLS - 5) break;
      const s = start.map(function (v, i) {
        return (i >= 15) ? clamp(v + add) : v;
      });
      const rr = evaluate(type, s, H);
      if (rr && within(rr, th)) return { idx: s, res: rr };
    }

    // Then strengthen all groups.
    for (let add = 1; add <= 6; add++) {
      if (calls >= MAX_CALLS - 5) break;
      const s = start.map(function (v) { return clamp(v + add); });
      const rr = evaluate(type, s, H);
      if (rr && within(rr, th)) return { idx: s, res: rr };
    }

    return null;
  }

  function optimize(start, type, th, maxPasses, budget) {
    const H = (type === "split") ? H_SPLIT : undefined;
    const r0 = evaluate(type, start, H);
    if (!r0 || !within(r0, th)) return null;

    let cur = start.slice();
    let best = {
      idx: cur.slice(),
      mass: massOf(r0),
      res: r0
    };

    const NG = cur.length;
    const GL = (type === "split") ? GL_SPLIT : GL_BASE;

    for (let pass = 0; pass < maxPasses && calls < budget - 2; pass++) {
      let improved = false;
      const order = [];
      for (let g = 0; g < NG; g++) order.push(g);

      order.sort(function (a, b) {
        const ma = (AREA[clamp(cur[a])] || 0) * (GL[a] || 1);
        const mb = (AREA[clamp(cur[b])] || 0) * (GL[b] || 1);
        return mb - ma;
      });

      for (let oi = 0; oi < order.length && calls < budget - 2; oi++) {
        const g = order[oi];
        const ci = cur[g];
        if (ci <= 0) continue;

        const curArea = AREA[clamp(ci)];
        let maxPos = -1;
        for (let p = 0; p < sortedArea.length; p++) {
          if (AREA[sortedArea[p]] < curArea - 1e-9) maxPos = p;
          else break;
        }
        if (maxPos < 0) continue;

        let lo = 0;
        let hi = maxPos;
        let ansPos = -1;

        while (lo <= hi && calls < budget - 2) {
          const mid = (lo + hi) >> 1;
          const cand = sortedArea[mid];
          const trial = cur.slice();
          trial[g] = cand;
          const rr = evaluate(type, trial, H);
          if (rr && within(rr, th)) {
            ansPos = mid;
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        if (ansPos >= 0) {
          const newIdx = sortedArea[ansPos];
          if (AREA[newIdx] < curArea - 1e-9) {
            const trial = cur.slice();
            trial[g] = newIdx;
            const rr = evaluate(type, trial, H);
            if (rr && within(rr, th)) {
              cur = trial;
              improved = true;
              if (massOf(rr) < best.mass) {
                best = { idx: cur.slice(), mass: massOf(rr), res: rr };
              }
            }
          }
        }
      }

      const rr = evaluate(type, cur, H);
      if (rr && within(rr, th) && massOf(rr) < best.mass) {
        best = { idx: cur.slice(), mass: massOf(rr), res: rr };
      }

      if (!improved) break;
    }

    return best;
  }

  const baseRes = evaluate("base", baseIdx);
  let bestBase = {
    idx: baseIdx.slice(),
    mass: massOf(baseRes),
    res: baseRes
  };

  let bestSplit = null;

  // Primary new idea: braced central top chord plus split ties and split bracing.
  const startInfo = findValidStart(startSplit, "split", TH_SAFE);
  if (startInfo) {
    bestSplit = optimize(startInfo.idx, "split", TH_SAFE, 2, 340);
  }

  // Also polish the known attempt-6 fallback if there is budget left.
  if (baseRes && within(baseRes, TH_SAFE) && calls < MAX_CALLS - 4) {
    const optBase = optimize(baseIdx, "base", TH_SAFE, 1, MAX_CALLS);
    if (optBase && optBase.mass < bestBase.mass) bestBase = optBase;
  }

  if (bestSplit && bestSplit.mass < bestBase.mass) {
    return makeSplit(bestSplit.idx, H_SPLIT);
  }
  return makeBase(bestBase.idx);
}

