  const CHS = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2", "CHS60.3x4",
    "CHS76.1x3.2", "CHS76.1x4", "CHS88.9x4", "CHS88.9x5", "CHS114.3x4",
    "CHS114.3x5", "CHS139.7x5", "CHS139.7x6.3", "CHS168.3x5", "CHS168.3x6.3",
    "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
  ];
  const AREA = [
    2.54, 3.94, 4.53, 5.74, 7.07, 7.33, 9.06, 10.67, 13.18, 13.86,
    17.17, 21.16, 26.4, 25.65, 32.06, 37.09, 46.67, 53.06, 59.44, 82.62,
    98.61, 134.74, 154.68, 221.67
  ];
  const MAXIDX = 23;
  const NG = 26;
  const MAX_CALLS = 398;

  function clamp(k) {
    k = Math.floor(k);
    if (!(k >= 0)) k = 0;
    if (k > MAXIDX) k = MAXIDX;
    return k;
  }

  // Fixed central-spine topology.  Group index is the sizing variable.
  const SPECS = [];
  function pushSpec(a, b, g) {
    SPECS.push([a, b, g]);
  }

  for (let p = 0; p < 10; p++) {
    const g = Math.min(p, 9 - p);
    pushSpec("L" + p, "L" + (p + 1), g);
    pushSpec("R" + p, "R" + (p + 1), g);
  }
  for (let i = 0; i <= 8; i++) {
    const g = 5 + Math.min(i, 8 - i);
    pushSpec("C" + i, "C" + (i + 1), g);
  }
  for (let i = 0; i <= 9; i++) {
    const g = 10 + Math.min(i, 9 - i);
    pushSpec("C" + i, "L" + i, g);
    pushSpec("C" + i, "R" + i, g);
    pushSpec("C" + i, "L" + (i + 1), g);
    pushSpec("C" + i, "R" + (i + 1), g);
  }
  for (let i = 0; i <= 10; i++) {
    const g = 15 + Math.min(i, 10 - i);
    pushSpec("L" + i, "R" + i, g);
  }
  for (let p = 0; p < 10; p++) {
    const g = 21 + Math.min(p, 9 - p);
    if (p % 2 === 0) pushSpec("L" + p, "R" + (p + 1), g);
    else pushSpec("R" + p, "L" + (p + 1), g);
  }

  const NODES = [];
  for (let i = 0; i <= 9; i++) {
    NODES.push({
      id: "C" + i,
      x: (i + 0.5) * 3.61,
      y: -5.75,
      z: 0,
      joint: "pin"
    });
  }

  const GMAP = {};
  for (let i = 0; i < SPECS.length; i++) {
    const s = SPECS[i];
    GMAP[s[0] + "|" + s[1]] = s[2];
    GMAP[s[1] + "|" + s[0]] = s[2];
  }

  function make(idx) {
    const members = [];
    for (let i = 0; i < SPECS.length; i++) {
      const s = SPECS[i];
      members.push([
        s[0],
        s[1],
        "S690 " + CHS[clamp(idx[s[2]])]
      ]);
    }
    const nodes = [];
    for (let i = 0; i < NODES.length; i++) {
      nodes.push({
        id: NODES[i].id,
        x: NODES[i].x,
        y: NODES[i].y,
        z: NODES[i].z,
        joint: NODES[i].joint
      });
    }
    return {
      note: "S690 CHS central-spine underslung Warren truss with strengthened critical joints and robust margins",
      nodes: nodes,
      joints: {},
      members: members
    };
  }

  let calls = 0;
  const cache = {};

  function ev(idx) {
    const key = idx.join(",");
    if (cache[key] !== undefined) return cache[key];
    if (calls >= MAX_CALLS) return null;
    let r;
    try {
      r = analyse(make(idx));
    } catch (e) {
      r = { error: String(e) };
    }
    calls++;
    cache[key] = r;
    return r;
  }

  function massOf(r) {
    return (r && typeof r.mass === "number") ? r.mass : Infinity;
  }

  function within(r, th) {
    if (!r || r.error || r.ok === false) return false;

    const ac = (typeof r.alphaCr === "number") ? r.alphaCr : r.alphaCrMin;
    if (typeof ac === "number" && ac < th.alpha) return false;

    if (typeof r.frequency === "number" && r.frequency < th.freq) return false;

    const sagLim = (typeof r.sagLimit === "number") ? r.sagLimit : 120.3;
    if (typeof r.sag === "number" && r.sag > sagLim * th.sagFactor) return false;

    const swayLim = (typeof r.swayLimit === "number") ? r.swayLimit : 90.3;
    if (typeof r.sway === "number" && r.sway > swayLim * th.swayFactor) return false;

    if (typeof r.fatigueWorst === "number" && r.fatigueWorst > th.fatigue) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > th.maxUtil) return false;

    if (r.members) {
      for (let i = 0; i < r.members.length; i++) {
        const m = r.members[i];
        if (m && typeof m.util === "number") {
          if (m.util > th.maxUtil) return false;
          const mode = m.mode ? String(m.mode).toLowerCase() : "";
          if (mode.indexOf("fatigue") >= 0 && m.util > th.fatigue) return false;
        }
      }
    }

    if (r.cases) {
      for (let i = 0; i < r.cases.length; i++) {
        const c = r.cases[i];
        if (c && typeof c.maxUtil === "number" && c.maxUtil > th.maxUtil) return false;
      }
    }

    if (r.robustness === false) return false;
    if (r.robustness && typeof r.robustness === "object" && r.robustness.ok === false) return false;

    return true;
  }

  function idGroup(m, i, n) {
    if (!m) return undefined;
    if (m.group !== undefined) return m.group;
    if (m.id) {
      const str = String(m.id).trim();
      if (GMAP[str] !== undefined) return GMAP[str];
      const parts = str.split(/[-–—>|:\s]+/).filter(Boolean);
      if (parts.length >= 2) {
        let key = parts[0] + "|" + parts[1];
        if (GMAP[key] !== undefined) return GMAP[key];
        key = parts[0] + "|" + parts.slice(1).join("-");
        if (GMAP[key] !== undefined) return GMAP[key];
      }
    }
    if (n && n === SPECS.length && i >= 0 && i < SPECS.length) {
      return SPECS[i][2];
    }
    return undefined;
  }

  function strengthenStep(cur, r, th) {
    const add = new Array(NG).fill(0);
    let any = false;

    if (r && r.members && r.members.length) {
      const n = r.members.length;
      for (let i = 0; i < n; i++) {
        const m = r.members[i];
        if (!m) continue;
        const g = idGroup(m, i, n);
        if (g === undefined) continue;

        let bad = false;
        if (typeof m.util === "number") {
          if (m.util > th.maxUtil) bad = true;
          const mode = m.mode ? String(m.mode).toLowerCase() : "";
          if (mode.indexOf("fatigue") >= 0 && m.util > th.fatigue) bad = true;
        }
        if (bad && cur[g] < MAXIDX) {
          add[g] = 1;
          any = true;
        }
      }
    }

    let glob = false;
    if (r) {
      const ac = (typeof r.alphaCr === "number") ? r.alphaCr : r.alphaCrMin;
      if (typeof ac === "number" && ac < th.alpha) glob = true;
      if (typeof r.frequency === "number" && r.frequency < th.freq) glob = true;

      const sagLim = (typeof r.sagLimit === "number") ? r.sagLimit : 120.3;
      if (typeof r.sag === "number" && r.sag > sagLim * th.sagFactor) glob = true;

      const swayLim = (typeof r.swayLimit === "number") ? r.swayLimit : 90.3;
      if (typeof r.sway === "number" && r.sway > swayLim * th.swayFactor) glob = true;

      if (typeof r.fatigueWorst === "number" && r.fatigueWorst > th.fatigue) {
        for (let g = 15; g <= 25; g++) {
          if (cur[g] < MAXIDX) {
            add[g] = 1;
            any = true;
          }
        }
      }
    }

    if (glob) {
      for (let g = 0; g <= 14; g++) {
        if (cur[g] < MAXIDX) {
          add[g] = 1;
          any = true;
        }
      }
      for (let g = 21; g <= 25; g++) {
        if (cur[g] < MAXIDX) {
          add[g] = 1;
          any = true;
        }
      }
    }

    if (!any) {
      for (let g = 0; g < NG; g++) {
        if (cur[g] < MAXIDX) {
          add[g] = 1;
          any = true;
        }
      }
    }

    const out = cur.slice();
    for (let g = 0; g < NG; g++) {
      if (add[g]) out[g] = clamp(out[g] + 1);
    }
    return out;
  }

  function getValidStart(start, th, maxRounds) {
    let cur = start.slice();
    for (let round = 0; round <= maxRounds; round++) {
      if (calls >= MAX_CALLS - 2) return null;
      const r = ev(cur);
      if (!r) return null;
      if (within(r, th)) return { idx: cur.slice(), res: r };
      if (round === maxRounds) break;
      const next = strengthenStep(cur, r, th);
      let changed = false;
      for (let i = 0; i < NG; i++) {
        if (next[i] !== cur[i]) changed = true;
      }
      if (!changed) break;
      cur = next;
    }
    return null;
  }

  const sortedArea = [];
  for (let i = 0; i <= MAXIDX; i++) sortedArea.push(i);
  sortedArea.sort(function (a, b) { return AREA[a] - AREA[b]; });

  const GL = [
    14.44, 14.44, 14.44, 14.44, 14.44,
    7.22, 7.22, 7.22, 7.22, 3.61,
    58.32, 58.32, 58.32, 58.32, 58.32,
    16.6, 16.6, 16.6, 16.6, 16.6, 8.3,
    18.1, 18.1, 18.1, 18.1, 18.1
  ];

  function optimize(start, th, maxPasses, budget) {
    if (!start) return null;
    if (calls >= budget - 2) return null;

    const r0 = ev(start);
    if (!r0 || !within(r0, th)) return null;

    let cur = start.slice();
    let best = {
      idx: cur.slice(),
      mass: massOf(r0),
      res: r0
    };

    for (let pass = 0; pass < maxPasses; pass++) {
      if (calls >= budget - 2) break;
      let improved = false;

      const order = [];
      for (let g = 0; g < NG; g++) order.push(g);
      order.sort(function (a, b) {
        const ma = AREA[clamp(cur[a])] * GL[a];
        const mb = AREA[clamp(cur[b])] * GL[b];
        return mb - ma;
      });

      for (let oi = 0; oi < order.length && calls < budget - 2; oi++) {
        const g = order[oi];
        const ci = clamp(cur[g]);
        const curArea = AREA[ci];

        let maxPos = -1;
        for (let p = 0; p < sortedArea.length; p++) {
          if (AREA[sortedArea[p]] < curArea - 1e-9) maxPos = p;
          else break;
        }
        if (maxPos < 0) continue;

        let lo = 0;
        let hi = maxPos;
        let ansPos = -1;

        while (lo <= hi && calls < budget - 2) {
          const mid = (lo + hi) >> 1;
          const cand = sortedArea[mid];
          const trial = cur.slice();
          trial[g] = cand;
          const rr = ev(trial);
          if (rr && within(rr, th)) {
            ansPos = mid;
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        if (ansPos >= 0) {
          const newIdx = sortedArea[ansPos];
          if (AREA[newIdx] < curArea - 1e-9) {
            const trial = cur.slice();
            trial[g] = newIdx;
            const rr = ev(trial);
            if (rr && within(rr, th)) {
              cur = trial;
              improved = true;
              if (massOf(rr) < best.mass) {
                best = { idx: cur.slice(), mass: massOf(rr), res: rr };
              }
            }
          }
        }
      }

      if (calls < budget - 2) {
        const rr = ev(cur);
        if (rr && within(rr, th) && massOf(rr) < best.mass) {
          best = { idx: cur.slice(), mass: massOf(rr), res: rr };
        }
      }

      if (!improved) break;
    }

    return best;
  }

  // Known previous passing design, used only as a final safety fallback.
  const knownIdx = [
    19, 20, 20, 21, 20,
    18, 21, 22, 23, 23,
    19, 19, 18, 16, 16,
    18, 6, 11, 11, 10, 14,
    19, 19, 18, 15, 12
  ];

  // Robust starting points.  These strengthen the members that governed
  // in the previous attempt: mid diagonals, support/mid transverse ties,
  // mid top chords, and top-plane bracing.
  const robust1 = [
    19, 20, 20, 21, 21,
    18, 21, 22, 23, 23,
    19, 19, 18, 17, 17,
    19, 8, 12, 12, 12, 16,
    19, 19, 18, 16, 14
  ];

  const robust2 = [
    19, 20, 20, 21, 21,
    18, 21, 22, 23, 23,
    19, 19, 19, 18, 18,
    20, 9, 12, 12, 12, 17,
    19, 19, 19, 17, 15
  ];

  const TH_FINAL = {
    maxUtil: 0.62,
    fatigue: 0.60,
    alpha: 5.5,
    freq: 3.02,
    sagFactor: 0.85,
    swayFactor: 0.85
  };

  let finalIdx = null;

  if (calls < MAX_CALLS - 5) {
    let startInfo = null;
    const r1 = ev(robust1);

    if (r1 && within(r1, TH_FINAL)) {
      startInfo = { idx: robust1.slice(), res: r1 };
    } else {
      const r2 = ev(robust2);
      if (r2 && within(r2, TH_FINAL)) {
        startInfo = { idx: robust2.slice(), res: r2 };
      } else {
        startInfo = getValidStart(robust1, TH_FINAL, 6);
        if (!startInfo && calls < MAX_CALLS - 12) {
          startInfo = getValidStart(robust2, TH_FINAL, 6);
        }
      }
    }

    if (startInfo && calls < MAX_CALLS - 5) {
      const b = optimize(startInfo.idx, TH_FINAL, 2, MAX_CALLS - 2);
      if (b) {
        finalIdx = b.idx;
        let bestMass = b.mass;

        if (calls < MAX_CALLS - 3) {
          const p = optimize(finalIdx, TH_FINAL, 1, MAX_CALLS);
          if (p && p.mass < bestMass) {
            finalIdx = p.idx;
            bestMass = p.mass;
          }
        }
      }
    }
  }

  if (finalIdx) return make(finalIdx);

  return make(knownIdx);
}

function design(site, analyse) {
  // Through-truss below the deck: two Warren trusses at z = -4.15 / +4.15,
  // bottom chord at y = -5.8 m, bottom nodes at mid-panels, plus deck-level
  // (y = 0) plan truss and bottom plan truss. All pinned, no wires or rods.
  const H = 5.8;
  const MAT = "S460 ";
  // Ascending area order (index 0 = member omitted, only useful for plan groups)
  const cand = [null,
    "CHS48.3x3.2", "CHS60.3x4", "CHS76.1x4", "CHS88.9x4", "CHS114.3x4",
    "CHS114.3x5", "CHS139.7x5", "CHS168.3x5", "CHS139.7x6.3", "CHS168.3x6.3",
    "CHS193.7x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
  ];
  const groups = [];
  for (const p of ["TC", "BC", "DG"]) for (let z = 0; z <= 4; z++) groups.push(p + z);
  groups.push("FB", "TD", "BX", "BD");

  const note = "Pinned Warren through-truss under deck (bottom chord at y=-5.8, nodes at mid-panels) with deck-level and bottom plan bracing; zone-graded CHS S460 sections found by a margin-checked search.";

  function build(sel) {
    const nodes = [];
    const members = [];
    for (let j = 0; j <= 9; j++) {
      const x = 3.61 * j + 1.805;
      nodes.push({ id: "BL" + j, x: x, y: -H, z: -4.15, joint: "pin" });
      nodes.push({ id: "BR" + j, x: x, y: -H, z: 4.15, joint: "pin" });
    }
    const add = (a, b, g) => {
      const s = cand[sel[g]];
      if (s) members.push({ a: a, b: b, spec: MAT + s });
    };
    for (const S of ["L", "R"]) {
      const B = (S === "L") ? "BL" : "BR";
      for (let j = 0; j <= 9; j++) {
        const z = Math.min(j, 9 - j);
        add(S + j, S + (j + 1), "TC" + z);
        add(S + j, B + j, "DG" + z);
        add(B + j, S + (j + 1), "DG" + z);
      }
      for (let j = 0; j <= 8; j++) {
        add(B + j, B + (j + 1), "BC" + Math.min(j, 9 - j));
      }
    }
    for (let i = 0; i <= 10; i++) add("L" + i, "R" + i, "FB");
    for (let i = 0; i <= 9; i++) {
      add("L" + i, "R" + (i + 1), "TD");
      add("R" + i, "L" + (i + 1), "TD");
    }
    for (let j = 0; j <= 9; j++) add("BL" + j, "BR" + j, "BX");
    for (let j = 0; j <= 8; j++) {
      add("BL" + j, "BR" + (j + 1), "BD");
      add("BR" + j, "BL" + (j + 1), "BD");
    }
    return { note: note, nodes: nodes, joints: {}, members: members };
  }

  const t0 = Date.now();
  let calls = 0;
  const cache = {};
  let best = null;
  const timeUp = () => (Date.now() - t0 > 65000) || calls >= 390;

  function good(r) {
    if (!r || r.error || !r.ok) return false;
    if (typeof r.maxUtil === "number" && r.maxUtil > 0.82) return false;
    if (typeof r.sag === "number" && typeof r.sagLimit === "number" && r.sag > 0.9 * r.sagLimit) return false;
    if (typeof r.sway === "number" && typeof r.swayLimit === "number" && r.sway > 0.9 * r.swayLimit) return false;
    if (typeof r.fMin === "number" && r.fMin < 3.0) return false;
    if (typeof r.alphaCr === "number" && r.alphaCr < 3.5) return false;
    return true;
  }

  function ok(sel) {
    const key = groups.map(g => sel[g]).join(",");
    if (Object.prototype.hasOwnProperty.call(cache, key)) return cache[key];
    if (timeUp()) return false;
    calls++;
    const d = build(sel);
    let res = false;
    try {
      const r = analyse(d);
      res = good(r);
      if (res && (!best || r.mass < best.mass)) best = { mass: r.mass, design: d };
    } catch (e) {
      res = false;
    }
    cache[key] = res;
    return res;
  }

  const sel = {};
  for (const g of groups) sel[g] = 16;
  if (!ok(sel)) {
    for (const g of groups) sel[g] = 19;
    ok(sel);
  }

  // Coordinate descent: for each group find the smallest section that keeps the whole design ok.
  for (let pass = 0; pass < 3; pass++) {
    let changed = false;
    for (const g of groups) {
      if (timeUp()) break;
      const isVert = (g.startsWith("TC") || g.startsWith("BC") || g.startsWith("DG"));
      let lo = isVert ? 1 : 0;
      let hi = sel[g];
      const before = hi;
      while (lo < hi) {
        if (timeUp()) break;
        const mid = (lo + hi) >> 1;
        sel[g] = mid;
        if (ok(sel)) hi = mid; else lo = mid + 1;
      }
      sel[g] = hi;
      if (hi !== before) changed = true;
    }
    if (!changed || timeUp()) break;
  }

  if (best) return best.design;
  return build(sel);
}

function design(site, analyse) {
  // Central-chord pyramid truss below the deck.
  // Bottom chord C0..C9 runs along the centre line z = 0 at y = -5.8 (mid-panel x).
  // Each panel has four pinned diagonals from the deck nodes L/R (j, j+1) down to C_j.
  // The centre chord and the four diagonals per panel supply the z-restraint that the
  // attempt-1 mechanism lacked. Deck-level bracing (FB, TD) triangulates the deck.
  // All members are CHS. Sections are sized by a margin-checked coordinate descent.
  const NOTE = "Central-chord pyramid truss (bottom chord on z=0 at y=-5.8, four pinned diagonals per panel to deck nodes, deck-level FB/TD bracing), S690 CHS sized by a margin-checked search.";
  const cand = [
    "S690 CHS42.4x3.2", "S690 CHS48.3x3.2", "S690 CHS60.3x3.2", "S690 CHS60.3x4",
    "S690 CHS76.1x3.2", "S690 CHS76.1x4", "S690 CHS88.9x4", "S690 CHS88.9x5",
    "S690 CHS114.3x4", "S690 CHS114.3x5", "S690 CHS139.7x5", "S690 CHS168.3x5",
    "S690 CHS139.7x6.3", "S690 CHS168.3x6.3", "S690 CHS193.7x6.3", "S690 CHS193.7x8",
    "S690 CHS219.1x8", "S690 CHS244.5x8", "S690 CHS273x10", "S460 CHS323.9x10",
    "S690 CHS355.6x12.5", "S460 CHS406.4x12.5", "S460 CHS457x16"
  ];
  const groups = [];
  for (const p of ["DG", "TC", "TD", "CB"]) for (let k = 0; k <= 4; k++) groups.push(p + k);
  for (let k = 0; k <= 5; k++) groups.push("FB" + k);

  function build(sel) {
