    for (let j = 0; j <= 9; j++) {
      nodes.push({ id: "C" + j, x: 3.61 * j + 1.805, y: -5.8, z: 0, joint: "pin" });
    }
    const members = [];
    const add = (a, b, g) => { members.push({ a: a, b: b, spec: cand[sel[g]] }); };
    for (let j = 0; j <= 9; j++) {
      const k = Math.min(j, 9 - j);
      add("L" + j, "C" + j, "DG" + k);
      add("C" + j, "L" + (j + 1), "DG" + k);
      add("R" + j, "C" + j, "DG" + k);
      add("C" + j, "R" + (j + 1), "DG" + k);
      add("L" + j, "L" + (j + 1), "TC" + k);
      add("R" + j, "R" + (j + 1), "TC" + k);
      add("L" + j, "R" + (j + 1), "TD" + k);
    }
    for (let j = 0; j <= 8; j++) add("C" + j, "C" + (j + 1), "CB" + Math.min(j, 8 - j));
    for (let i = 0; i <= 10; i++) add("L" + i, "R" + i, "FB" + Math.min(i, 10 - i));
