    }
    const u = utilOf(r);
    const ns = sel.map((k, i) => {
      if (u[i] === null) return k;
      const need = cand[k][1] * Math.max(u[i], 0.03) / T;
      let j = atLeast(need);
      j = Math.min(Math.max(j, k - 3), k + 2, TOP);
      return Math.max(j, floor[typ[i]]);
    });
    if (ns.every((v, i) => v === sel[i])) break;
    sel = ns;
    r = run(sel);
  }

  // 2) If nothing better than the fallback was found, grow the whole structure a little.
  if (!best) {
    for (let k = 0; k < 3 && !timeUp(); k++) {
      const base = best ? best.sel : sel;
      const grown = base.map(v => Math.min(TOP, v + 1));
      run(grown);
      if (best) break;
    }
  }

  // 3) Group shrink from the best passing design.
  if (best) {
    for (let pass = 0; pass < 3 && !timeUp(); pass++) {
      const before = best.mass;
      for (const g of GROUPS) {
        if (timeUp() || !best) break;
        const base = best.sel.slice();
        const t = base.map((v, i) => (typ[i] === g && v > floor[g] && v > 0 ? v - 1 : v));
        if (t.every((v, i) => v === base[i])) continue;
        run(t);
      }
      if (!best || best.mass >= before - 1e-9) break;
    }
  }

  // 4) Shrink lightly loaded members of the best design.
  if (best && !timeUp()) {
    const u = utilOf(best.r);
    const base = best.sel.slice();
    const t = base.map((v, i) => (u[i] !== null && u[i] < 0.3 && v > floor[typ[i]] && v > 0 ? v - 1 : v));
    if (!t.every((v, i) => v === base[i])) run(t);
  }

  if (best) return build(best.sel);
  return build(pm.map(() => ALL));
}
